.sl-slider-hero {
    position: relative;
    background-color: var(--smartlearn-bg);
    font-family: var(--smartlearn-body-font, inherit);
    overflow: hidden;
}
.sl-slider-hero .carousel-inner { touch-action: pan-y; }
.sl-slider-hero .carousel-item { height: 80vh; min-height: 500px; max-height: 800px; }
.sl-slider-hero .sl-hero-bg { position: absolute; inset: 0; width: 100%; height: 100%; z-index: 1; }
.sl-slider-hero .sl-hero-bg img { width: 100%; height: 100%; object-fit: cover; }
.sl-slider-hero .sl-hero-overlay { position: absolute; inset: 0; background: rgba(15, 23, 42, 0.56); z-index: 2; }
.sl-slider-hero .sl-hero-caption {
    z-index: 3;
    top: 50%;
    bottom: auto;
    inset-inline: 10%;
    transform: translateY(-50%);
    padding-inline: 0;
    text-align: center;
}
.sl-slider-hero .sl-hero-title {
    font-family: var(--smartlearn-heading-font, inherit);
    font-size: clamp(2rem, 4.5vw, 3.5rem);
    font-weight: 800;
    color: #fff;
    margin-bottom: 1.25rem;
    line-height: 1.2;
    text-shadow: 0 2px 10px rgba(0,0,0,0.35);
    animation: sl-slider-hero-fade-up 0.8s ease forwards;
}
.sl-slider-hero .sl-hero-subtitle {
    font-size: clamp(1rem, 2vw, 1.25rem);
    font-weight: 500;
    color: #f8f9fa;
    margin-bottom: 2rem;
    text-shadow: 0 1px 5px rgba(0,0,0,0.35);
    animation: sl-slider-hero-fade-up 1s ease forwards;
}
.sl-slider-hero .sl-hero-actions {
    display: flex;
    gap: 1rem;
    justify-content: center;
    flex-wrap: wrap;
    animation: sl-slider-hero-fade-up 1.2s ease forwards;
}
.sl-slider-hero .sl-btn-hero {
    background-color: var(--smartlearn-btn-bg);
    color: var(--smartlearn-btn-text);
    border: 1px solid transparent;
    padding: 0.875rem 2rem;
    font-weight: 700;
    border-radius: var(--smartlearn-radius, 0.5rem);
    font-size: 1.0625rem;
}
.sl-slider-hero .sl-btn-hero:hover,
.sl-slider-hero .sl-btn-hero:focus-visible {
    background-color: var(--smartlearn-btn-hover-bg);
    color: var(--smartlearn-btn-text);
}
.sl-slider-hero .sl-btn-hero-outline {
    padding: 0.875rem 2rem;
    font-weight: 700;
    border-radius: var(--smartlearn-radius, 0.5rem);
    font-size: 1.0625rem;
    border-width: 2px;
}
.sl-slider-hero .sl-hero-indicators { margin-bottom: 1.5rem; z-index: 4; gap: 0.25rem; }
.sl-slider-hero .sl-hero-indicators button[data-sl-slide-to] {
    width: 44px !important;
    height: 28px !important;
    padding: 11px 4px !important;
    background-clip: content-box !important;
    background-color: rgba(255,255,255,0.5) !important;
    border: none !important;
    margin: 0 2px !important;
    opacity: 1 !important;
    transition: background-color 0.3s ease;
}
.sl-slider-hero .sl-hero-indicators button[data-sl-slide-to].active {
    background-color: #fff !important;
}
.sl-slider-hero .sl-carousel-pause {
    width: 32px !important;
    height: 32px !important;
    border-radius: 50%;
    background: rgba(15, 23, 42, 0.65) !important;
    color: #fff !important;
    border: 1px solid rgba(255,255,255,0.4) !important;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    margin-inline-start: 0.5rem;
    text-indent: 0 !important;
    opacity: 1 !important;
}
.sl-slider-hero .sl-hero-control {
    z-index: 4;
    width: 10%;
    min-width: 44px;
    opacity: 0;
    transition: opacity 0.3s ease;
}
.sl-slider-hero:hover .sl-hero-control,
.sl-slider-hero .sl-hero-control:focus-visible { opacity: 0.9; }
.sl-slider-hero .sl-hero-control:hover { opacity: 1 !important; }
@media (hover: none) {
    .sl-slider-hero .sl-hero-control { opacity: 0.85; }
}
.sl-slider-hero .sl-hero-control:focus-visible,
.sl-slider-hero .sl-hero-indicators button:focus-visible,
.sl-slider-hero .sl-btn-hero:focus-visible {
    outline: 3px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
[dir="rtl"] .sl-slider-hero .carousel-control-prev-icon,
[dir="rtl"] .sl-slider-hero .carousel-control-next-icon {
    transform: scaleX(-1);
}
@keyframes sl-slider-hero-fade-up {
    from { opacity: 0; transform: translateY(24px); }
    to { opacity: 1; transform: translateY(0); }
}
@media (max-width: 767px) {
    .sl-slider-hero .carousel-item { height: 70vh; min-height: 460px; }
    .sl-slider-hero .sl-hero-caption { inset-inline: 1rem; }
    .sl-slider-hero .sl-hero-actions { flex-direction: column; width: 100%; max-width: 300px; margin: 0 auto; }
}
@media (prefers-reduced-motion: reduce) {
    .sl-slider-hero .sl-hero-title,
    .sl-slider-hero .sl-hero-subtitle,
    .sl-slider-hero .sl-hero-actions { animation: none; }
    .sl-slider-hero .sl-hero-control,
    .sl-slider-hero .sl-hero-indicators button { transition: none; }
}

